questionvariables.text:
a:rand(3)+1;
correct_answer:rand_selection([
[1, true, "A life table measures literacy levels of a country"],
[2, true, "A life table predicts weather patterns"],
[3, true, "A life table analyzes economic growth rates"],
[4, true, "A life table predicts stock market fluctuations"]],a);

b:4-a;
incorrect_answers:rand_selection([
[5, false, "A life table is a Mathematical model"],
[6, false, "A life table provides a basis for measuring life expectancy"],
[7, false, "A life table can be used to investigate morbidity"],
[8, false, "A life table provides a basis for measuring infant mortality"],
[9, false, "A life table portrays the mortality conditions at a particular time among a population"],
[10, false, "A life table provides a basis for measuring longevity"]], b);

ta:random_permutation(append(correct_answer,incorrect_answers));
ta_index: sort(makelist(x[1], x, ta));
